// checkVoteRateLimit implements per-user per-contestant daily rate limiting (Atomic)
func (r *mutationResolver) checkVoteRateLimit(ctx context.Context, userID, contestantID string) error {
	// Key format: vote_limit:YYYYMMDD:userID:contestantID
	date := time.Now().Format("20060102")
	key := fmt.Sprintf("vote_limit:%s:%s:%s", date, userID, contestantID)

	// Increment atomically
	count, err := r.CacheSvc.Incr(ctx, key)
	if err != nil {
		// Log error and fail closed for security in a contest
		log.Printf("[SECURITY] Rate limit cache error: %v", err)
		return errors.New("hệ thống đang bận, vui lòng thử lại sau")
	}

	// Set expiry (24h is enough as the key contains the date)
	if count == 1 {
		_ = r.CacheSvc.Set(ctx, key, "1", 24*time.Hour)
	}

	// If count > 1, they already voted today
	if count > 1 {
		return errors.New("bạn đã bình chọn cho thí sinh này trong hôm nay rồi")
	}

	return nil
}

// VoteForContestant is the resolver for the voteForContestant field.
func (r *mutationResolver) VoteForContestant(ctx context.Context, id string) (bool, error) {
	// Authentication check
	userID := middleware.ForContext(ctx)
	if userID == "" {
		return false, errors.New("unauthorized")
	}

	// Rate limit check (1 vote per user per contestant per day)
	if err := r.checkVoteRateLimit(ctx, userID, id); err != nil {
		return false, err
	}

	// Get Client Info
	ip, ua := middleware.GetClientInfo(ctx)

	// Call Service
	if err := r.ContestantSvc.VoteForContestant(ctx, userID, id, ip, ua); err != nil {
		return false, err
	}

	return true, nil
}

