// PublicContestants is the resolver for the publicContestants field.
func (r *queryResolver) PublicContestants(ctx context.Context, page *int, limit *int) ([]*model.Contestant, error) {
	// Normalize pagination
	p, l := validation.NormalizePagination(page, limit)
	offset := int64((p - 1) * l)
	limit64 := int64(l)

	// 1. Try Cache First (if it's the first page)
	cacheKey := fmt.Sprintf("public_contestants:p%d:l%d", p, l)
	var cachedRes []*model.Contestant
	if err := r.CacheSvc.Get(ctx, cacheKey, &cachedRes); err == nil && cachedRes != nil {
		return cachedRes, nil
	}

	// 2. Cache Miss: Fetch from DB
	list, _, err := r.ContestantSvc.GetPublicList(ctx, limit64, offset)
	if err != nil {
		return nil, err
	}

	var res []*model.Contestant
	for _, c := range list {
		res = append(res, mapPublicContestantToGraph(c))
	}

	// 3. Save to Cache (Optimize: 5 minutes TTL for list)
	if err := r.CacheSvc.Set(ctx, cacheKey, res, 5*time.Minute); err != nil {
		log.Printf("[Cache] Failed to set public contestants: %v", err)
	}

	return res, nil
}

